package kr.yunseok.touchmacro;
import java.util.Arrays;import org.junit.Test;import static org.junit.Assert.*;
public class OcrWordBoundaryTest {
 @Test public void phrasesUseOriginalSpacingAndElementEndpoints(){assertArrayEquals(new int[]{0,1},TextRules.elementSpans("Adobe Pro 15",Arrays.asList("Adobe","Pro","15"),"Adobe Pro").get(0));assertEquals(2,TextRules.elementSpans("Adobe Adobe",Arrays.asList("Adobe","Adobe"),"Adobe").size());assertTrue(TextRules.elementSpans("Adobe  Pro",Arrays.asList("Adobe","Pro"),"Adobe Pro").isEmpty());assertTrue(TextRules.elementSpans("AdobePro",Arrays.asList("AdobePro"),"Adobe").isEmpty());assertTrue(TextRules.elementSpans("AdobePro",Arrays.asList("Adobe","Pro"),"Adobe").isEmpty());}
 @Test public void independentWordsAndRepeatedWordsKeepOffsets(){assertArrayEquals(new int[]{0,6},TextRules.elementStarts("Adobe Adobe",Arrays.asList("Adobe","Adobe")));assertTrue(TextRules.completeElement("Adobe Pro",0,5));assertTrue(TextRules.completeElement("Adobe 15",0,5));}
 @Test public void attachedLettersDigitsAndConnectorsAreNotWholeWords(){for(String text:Arrays.asList("AdobePro","Adobe15","Adobe_Pro","Adobe\u200BPro","Adobe\u0301"))assertFalse(text,TextRules.completeElement(text,0,5));assertFalse(TextRules.completeElement("XAdobe",1,6));assertFalse(TextRules.completeElement("\uD801\uDC00Adobe",2,7));}
 @Test public void ambiguousOrOmittedSourceCharactersAreNotInvented(){assertNull(TextRules.elementStarts("Adobe X Pro",Arrays.asList("Adobe","Pro")));assertNull(TextRules.elementStarts("Adobe Pro",Arrays.asList("Pro","Adobe")));assertNull(TextRules.elementStarts("Adobe\u200BPro",Arrays.asList("Adobe","Pro")));assertArrayEquals(new int[]{0,5},TextRules.elementStarts("AdobePro",Arrays.asList("Adobe","Pro")));assertFalse(TextRules.completeElement("AdobePro",0,5));}
 @Test public void literalQueryStillHasNoAliasCaseOrWhitespaceNormalization(){TextRules.Prepared rule=TextRules.prepareExact("Adobe");for(String actual:Arrays.asList("어도비","ADOBE","Ａｄｏｂｅ"," Adobe","Adobe ","AdobePro"))assertFalse(actual,rule.matches(actual));assertTrue(rule.matches("Adobe"));}
}
